          "summary": "LINK : https://www.nepc.com/advertised-searches/massachusetts-water-resources-authority-mwra-retirement-system-private-equity-middle-market-buyout-strategies-rfp/ The MWRA Employees’ Retirement System is seeking proposals from qualified investment managers for a Private Equity Middle Market Buyout mandate on behalf of its approximately $835 million defined benefit pension fund. To be considered, candidates must be actively raising a private closed-end middle market buyout private equity fund. The System anticipates committing up to $20 million to the selected mandate. The Board will not consider mega buyout funds, co-investment-only vehicles, or fund-of-funds strategies as part of this search. The mandate is focused exclusively on middle market buyout opportunities that align with the System’s investment objectives. The Board reserves the right to cancel or reject any or all proposals, in whole or in part, if deemed to be in the best interest of the Retirement System. Interested managers may obtain the RFP through the NEPC website and must submit proposals electronically to the designated search email address by the stated deadline."
