          "summary": "LINK : https://www.mass.gov/info-details/cambridge-retirement-board-request-for-proposal The Cambridge Retirement Board is seeking proposals from qualified law firms to provide portfolio monitoring and securities litigation services on a contingency fee/no-cost basis. The Board may select one or more firms to support the System in monitoring investment portfolios and pursuing securities litigation matters when appropriate. The Cambridge Retirement Board administers a governmental defined benefit pension plan with approximately $2.1 billion in assets and serves approximately 6,600 active and retired members and beneficiaries. The System covers employees of the City of Cambridge, Cambridge Health Alliance, Cambridge Housing Authority, and Cambridge Redevelopment Authority. All investments made by the Board are subject to Massachusetts General Laws Chapter 32, as amended by Chapter 176 of the Acts of 2011, and the regulations of the Public Employees Retirement Administration Commission (PERAC), 840 CMR. Selected firms must demonstrate familiarity with and agree to comply with all applicable laws, regulations, and disclosure requirements. The Board reserves the right to cancel or reject any or all proposals, in whole or in part, if deemed to be in the best interest of the System. Timeline Item Date RFP Available Available upon request via email until proposal deadline Proposal Due July 27, 2026 – 5:00 PM EDT Proposal Opening Not specified Expected Award Decision Not specified Interested firms may obtain a copy of the Request for Proposal by submitting a request via email to Chris Burns, Executive Director."
