          "swfi_url": "https://www.swfi.com/v1/compass/6a3a8089857280a03b24a2f8",
          "summary": "LINK : https://www.mass.gov/info-details/methuen-retirement-board-request-for-proposal The Methuen Retirement Board is requesting qualification statements from recognized law firms and individual attorneys within the Commonwealth of Massachusetts interested in providing legal services to the Methuen Retirement System. The selected legal counsel will be expected to advise and represent the Board on matters involving Massachusetts public pension law in accordance with Chapter 32 of the General Laws of Massachusetts and the Commonwealth of Massachusetts Regulations 840 CMR administered by the Public Employee Retirement Administration Commission (PERAC). Interested firms and attorneys must submit qualification statements for consideration. Late submissions will not be evaluated. Email: kdoucette@methuen.gov Submission Method: Proposals must be submitted electronically via email. Submission Deadline: August 21, 2026, at 12:00 PM EST"
