          "asset_class_or_strategy": "Private Equity Fund",
          "strategy": "Private Equity Fund",
          "investment_type": "Private Equity Fund",
          "investment_type_children": [
            "Growth Equity",
            "Buyout Large",
            "Late Stage Venture",
            "Special Situations Debt"
          ],
          "amount": 3000000000,
          "value": 3000000000,
          "currency": "USD",
          "amount_display": "$3,000,000,000",
          "country": "Singapore",
          "region": "Asia",
          "city": "Singapore",
          "deadline": "2026-09-01",
          "due_at": "2026-09-01",
          "posted_at": "2025-09-01",
          "relevant_date": "2026-09-01",
          "attachment_url": "",
          "source_url": "https://www.swfi.com/v1/compass/68b5b49fd07b9e3966244f30",
          "swfi_url": "https://www.swfi.com/v1/compass/68b5b49fd07b9e3966244f30",
          "summary": "SWFI expects Temasek to make major changes in how it invests in funds. The process will likely be more streamlined, the SWF will likely commit more to PE funds and growth equity funds Before 2011, Temasek Holdings was primarily Temasek Holdings and in 2011 they created Temasek International. Employees at Temasek Holdings were transferred to Temasek international. There’s only one employee in Temasek Holdings since 2011. That’s the CEO. Everybody else is in TI. Temasek Holdings it’s not just a company that was incorporated under the Companies Act. It’s also a Fifth Schedule entity under the Constitution. They have responsibilities, not just their shareholder, but also to the President for protection of the reserves which are attributable to Temasek. The Board of Temasek Holdings and the CEO are responsible for the entire portfolio, all the entities. On April 1, 2026, Temasek is moving to change its corporate structure to: 1. Temasek International (group and corporate functions) 2. Temasek Global Investments (global direct investments) 3. Temasek Singapore (Temasek portfolio companies) 4. Temasek Partnership Solutions (Partnerships and funds, asset management (Seviora Holdings)) The estimated amount is based on pacing and historical activities."
