          "summary": "The Ontario Teachers Pension Plan (OTPP) revealed plans to target up to 10% of assets for its Teachers Innovation Platform (TIP) by 2026. In a 5-year basis, OTPP seeks to have the innovation platform to be between 8% to 10%. The bold goal includes finding more private investments. The current allocation is at 3% today. OTPP sees tremendous opportunities in the disruptive tech space, spanning sectors. TIP's growth is expected to come from both increasing revenues and profits at the firms the fund invests in, and further allocations of capital to the TIP team to lead investments, participate in syndicates, and provide “complementary” capital to support the late-stage venture and growth equity investments. TIPS was created in the spring of 2019. TIP's inaugural investment was in Elon Musk's SpaceX. Amount is an estimate."
