          "summary": "LINK : https://www.un.org/Depts/ptd/sites/www.un.org.Depts.ptd/files/pdf/eoi24516.pdf The United Nations Joint Staff Pension Fund (UNJSPF), through its Office of Investment Management (OIM), is seeking Expressions of Interest (EOI) from experienced institutional investment consultants to provide advisory services for its externally managed investment portfolio. Eligible consultants must have a minimum of five years of experience advising large institutional investors and must demonstrate experience serving at least five institutional clients, each with assets exceeding $50 billion as of Q1 2026 and utilizing external investment managers. Respondents must disclose their client base, assets under advisement, and relevant consulting experience. The scope of services includes investment research across equities, fixed income, and specialty strategies; strategic and tactical asset allocation advice; portfolio oversight; manager searches and recommendations; performance monitoring; risk management and factor analysis; customized benchmark advisory; evaluation of manager contributions at both portfolio and total fund levels; and access to proprietary or third-party investment databases. Consultants must also demonstrate structured processes for portfolio construction, manager evaluation, ongoing monitoring, governance support, investment policy advisory services, and data infrastructure capabilities. Additionally, respondents are required to provide detailed information regarding firm ownership, organizational structure, client composition, research resources, compliance framework, and key personnel assigned to the engagement. The EOI is being conducted by the United Nations Procurement Division (UNPD). Interested firms must be registered with the United Nations Global Marketplace (UNGM) and submit their expressions of interest through the UNGM portal before the submission deadline."
