          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_02.pdf The job performance contents focus on direct management of domestic bonds, including government bonds, credit bonds, and bond-related derivatives and structured products. Responsibilities include establishing the National Pension Fund’s bond investment strategy, managing short-term won-denominated funds, selecting and managing domestic bond issuance and auction trading institutions, and composing investable issuer groups such as corporate bonds with credit management. Additional tasks include portfolio status analysis and monitoring, developing bond investment strategies, and overseeing other matters related to government bond and credit bond investment. The competency units cover corporate analysis, bond investment strategy development, stock/bond portfolio composition, and the establishment of bond investment goals. These are essential to ensure the sound management of NPS’s large-scale domestic bond investments. Required Skills & Knowledge Candidates must demonstrate strong knowledge of National Pension Fund-related regulations, capital markets, capital market laws, and financial investment business regulations. Proficiency in financial mathematics, statistics, and financial analysis is critical. Skills in office program utilization, statistical software application, interpretation and application of laws, and overall data analysis are required. Logical and analytical thinking, professional ethics, communication skills, negotiation, and objective judgment are also essential, alongside adaptability to new information and economic environments. Career Requirements Applicants must have at least three years of full-time investment manager experience and at least one month of relevant job experience in stock/bond management. Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM, CAIA, Tax Accountant, Financial Investment Analyst, Investment Asset Management Company Specialist, Fund Investment Recommendation Advisor, Securities Investment Recommendation Advisor, Derivatives Investment Recommendation Advisor, Financial Risk Manager, Futures Trading Consultant, Derivatives Investment Consultant, and Asset Manager. Holding these qualifications strengthens credibility and expertise in managing complex bond portfolios. Due date is estimated."
