          "investors": "UC Investments (the University of California Office of the Chief Investment Officer), Wisconsin Alumni Research Foundation (WARF), Octave Ventures, and Phoenix Venture Partners.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Qolab Inc., a Santa Barbara, CA-based quantum computing hardware company, announced the initial closings of its Series B Preferred Stock financing. Together with the conversion of an aggregate of $12.6m in convertible securities and a commitment for an aggregate of $10m in future convertible securities, it represents total funding of $54.2m. The round was led by UC Investments (the University of California Office of the Chief Investment Officer) with participation from existing financial and strategic semiconductor investors including Wisconsin Alumni Research Foundation (WARF), Octave Ventures, and Phoenix Venture Partners. The company intends to use the funds for continued development of scalable superconducting quantum computing technologies, expansion of strategic semiconductor collaborations, and acceleration its target toward fault-tolerant quantum computing. Led by Alan Ho, co-founder and CEO, Qolab is a hardware company developing utility-scale superconducting quantum computers combining deep physics and engineering expertise with strategic semiconductor partnerships. Qolab collaborates with Lawrence Berkeley National Laboratory through the Quantum Systems Accelerator — a U.S. Department of Energy National Quantum Information Science Research Center led by the Berkeley Lab — and with researchers from UC Santa Barbara to explore next-generation quantum algorithms using Qolab technologies.",
