          "investors": "Denali Growth Partners and Taiwania Capital.",
          "note": "SWFI estimated equal contribution.",
          "summary": "Luxonis, a Denver, CO-based robotics and industrial automation company advancing the OAK camera and DepthAI software, closed a $14m Series A funding round. The round was led by Denali Growth Partners, with participation from Taiwania Capital. The company intends to use the funding will accelerate commercial expansion, advance the product roadmap, and scale production of its OAK camera platform. The investment will expand supply chain capacity and advance the OAK4 ecosystem which launched in December 2025. Led by Bradley Dillon, CEO, Luxonis builds the perception layer that robots and automated systems need to operate in the real world. Its OAK camera devices combine multiple sensors and on-device compute into a single unit, paired with an open-source software ecosystem that lets developers use agentic AI to rapidly build and deploy automation for any use case that requires visual perception. The company plans to expand R&D, go-to-market and engineering-support teams to work directly with more customers on production deployments. New devices are planned to launch in flexible form factors for many industries including agriculture, advanced robotics, defense, industrial automation, heavy machinery, medtech, and warehousing.",
