          "summary": "Alkimii, a Skerries, Ireland-based developer of workforce and operations management software for the hospitality sector, received an investment from August Equity. The amount of the deal was not disclosed. The company intends to use the funds to accelerate its commercial go-to-market strategy, finance the development of new product functionality, and scale its market presence across the United Kingdom and Europe. Led by Founder and CEO Ronan McAuley, Alkimii develops a verticalized workforce management and operational compliance platform engineered to optimize staff visibility, property management, and service consistency for hotels and hospitality providers. The company officially appointed enterprise technology veteran Henry Seddon as corporate Chairman, and expanded its platform utility to serve over 50 percent of all hotel employees across Ireland.",
