          "investment_type": "Convertible",
          "investors": "AVP, Atinum Investment, GFT Ventures, with participation from SBI Investment, Z Venture Capital, Betatron Venture Group, East Ventures, SV Investment, Samsung Securities, Mirae Asset Venture Investment, Mirae Asset Capital, NH Investment & Securities, Shinhan Venture Investment, and Hana Ventures.",
          "note": "SWFI estimated equal contribution.",
          "summary": "LinqAlpha, a NYC-based AI-native company building the Alpha Intelligence Layer for global public markets, raised $22m in Series A funding. The round was anchored by AVP, Atinum Investment, and GFT Ventures, with participation from SBI Investment, Z Venture Capital, Betatron Venture Group, East Ventures, SV Investment, Samsung Securities, Mirae Asset Venture Investment, Mirae Asset Capital, NH Investment & Securities, Shinhan Venture Investment, and Hana Ventures. The company intends to use the new capital to expand its global team, deepen integrations across market and alternative datasets, and accelerate the deployment of its multi-agent platform across equities, macro, credit, and multi-asset strategies. Founded by Jacob Choi, Subeen Pang, Jin Kim, and Hojun Choi, LinqAlpha is building a platform that lets institutional investors deploy specialized AI agents that learn each user’s investment framework and synthesize data into actionable insight. Since launch, the platform has seen rapid adoption, serving over 70 financial institutions across the U.S., Europe, and Asia, including sell-side sales, trading, and research teams at leading investment banks, as well as buy-side clients such as Causeway Capital Management LLC and Schonfeld Strategic Advisors LLC. Collectively, LinqAlpha’s buy-side clients manage more than $5 trillion in assets.",
          "source_url": "https://www.swfi.com/v1/transactions/6a4625991c7c9d06cde47eb5",
          "swfi_url": "https://www.swfi.com/v1/transactions/6a4625991c7c9d06cde47eb5"
