          "note": "SWFI estimated equal contribution.",
          "summary": "Omni, a London, UK-based developer of vet-formulated plant-based pet food and supplements, raised $14.6m in Series A funding. The round was co-led by IW Capital and Redrice Ventures, with participation from RootBridge Capital, Digitalis Ventures, Lever VC, and existing investor Deborah Meaden. The company intends to use the capital to accelerate its retail distribution footprint across the United Kingdom, expand its functional product development pipeline, and invest in multi-channel consumer marketing campaigns. Led by Co-founders Dr. Guy Sandelowsky and Shiv Sivakumar, Omni develops alternative meat-free dog food formulations and dietary supplements engineered to treat canine health conditions, including severe allergies, chronic gut issues, behavioral anxiety, and clinical weight problems.",
