          "note": "",
          "summary": "Hilb Group announced that it has acquired a Louisiana-based property and casualty agency. The acquisition takes effect and builds on the company's growing presence in the Central region. The Hilb Group is a leading property and casualty and employee benefits insurance brokerage and advisory firm headquartered in Richmond, Virginia. Hilb Group is a portfolio company of The Carlyle Group, a global investment firm. Hilb Group seeks to grow through strategic acquisitions and by leveraging its resources and expertise to drive organic growth in its acquired agencies. The company has completed more than 200 acquisitions with over 125 offices in 32 states.",
