          "note": "",
          "summary": "Arcline Investment Management (\"Arcline\"), a growth-oriented private equity firm, announced it has entered into a definitive agreement to acquire Avantus Aerospace Group Limited (\"Avantus\" or \"the Company\"), a leading provider of engineered shims and fasteners for the global aerospace and defense industries, from Inflexion. Avantus and its subsidiaries will operate as brands of Novaria Group, an Arcline portfolio company. Financial terms of the transaction were not disclosed. Avantus products are embedded on virtually every major commercial, business jet, and defense aircraft platform in production serving over 1,600 customers worldwide with more than 25 million units delivered annually. Through its eight established brands, Avantus is a leader in the manufacture and design of engineered shims, solid fillers, and detail parts used to manage critical gaps during aircraft production, as well as a range of specialty fasteners, including captive screws, structural bolts, headed pins, and complex engine fasteners. Lazard is serving as financial advisor to Arcline, and Ropes & Gray LLP is serving as legal counsel. Perella Weinberg Partners is serving as exclusive financial advisor to Avantus and Inflexion, and Willkie Farr & Gallagher LLP is serving as legal counsel.",
