          "summary": "Kimball Electronics, Inc. (Nasdaq: KE) announced the Company acquired Helvoet Polymer Technologies B.V. (“Helvoet”), a Contract Development and Manufacturing Organization (CDMO), based in Europe and with operations in India focused on microfluidics, diagnostics, and drug delivery. The transaction was valued at a purchase price of €90 million (excluding working capital, other customary adjustments, and acquisition-related costs), or approximately $103 million, representing approximately 9x estimated adjusted EBITDA for Helvoet in calendar 2026. Kimball funded the acquisition through a combination of cash and available borrowing capacity on existing lines of credit. Pro forma leverage following the close remains consistent with the capital allocation priorities of Kimball.",
