          "note": "",
          "summary": "CoStar Group, Inc. (NASDAQ: CSGP), a global leader in online real estate marketplaces, information, analytics and 3D digital twin technology in the property markets, announced an investment in Wikicasa, Italy’s agent-backed real estate marketplace. The transaction will result in CoStar Group acquiring an approximately 30% stake in Wikicasa. Wikicasa’s shareholder base includes Italy’s leading real estate agencies - including Tecnocasa Group, Gabetti Group, RE/MAX Italy, and Tempocasa. Wikicasa.it is an agent-driven platform that brings together leading real estate professionals across Italy to deliver a high-quality, data-rich marketplace of over 600,000 listings, more than 100,000 of which are commercial. It provides consumers with comprehensive property listings while equipping agents with modern data and intelligence tools to market properties and connect with buyers, sellers, landlords and tenants.",
