          "note": "SWFI estimated equal contribution.",
          "summary": "CarbonSix, Inc., a San Francisco, CA-based Physical AI company focused on the manufacturing sector, raised $40m (approx. KRW 60 billion) in Series A funding. The round was co-led by DSC Investment and LB Investment, with participation from new investors IMM Investment, Korea Development Bank (KDB), SV Investment, Cortentia (U.S.), and ASQ (A Squared, U.S.), and all existing investors Foothill Ventures, Storm Ventures, Zeitgeist Capital, Xquared and CarbonBlack Fund. The company intends to use the funds to expand operations and its development efforts. CarbonSix is a Physical AI company developing deployment-ready robotic intelligence and automation solutions for manufacturing. Its technologies help manufacturers automate complex, variable tasks while improving performance through real-world operational data. . The company provides practical automation tools that factories can use immediately. As clients operate these tools, high-quality, task-specific data is naturally captured and fed back into the system.",
